"""Study results for the web app, generated by the runners (Phase 14, ADR-072).

`/research` cards used to carry hand-copied numbers, which drifted from the reports (the MS-057 card kept
an interval the report had since corrected). Each runner now records its primary estimate in
apps/web/lib/generated/study-results.json, keyed by card ID, together with the counts and provenance of
the run. The cards keep their prose and read the numbers from this file.
"""

from __future__ import annotations

import json
from pathlib import Path

from . import provenance
from .lake import store

GENERATED = store.REPO / "apps/web/lib/generated/study-results.json"


def record_result(card: str, value: float, low: float, high: float, *, digits: int = 3,
                  positions: int | None = None, games: int | None = None, weeks: int | None = None,
                  dataset: str | None = None, report: str | None = None, path: Path = GENERATED) -> dict:
    """Upsert one card's primary result. Numbers are stored unrounded (to 6 places); `digits` is how
    the card displays them."""
    commit, dirty = provenance.git_state()
    entry = {"value": round(float(value), 6), "low": round(float(low), 6), "high": round(float(high), 6),
             "digits": digits, "positions": positions, "games": games, "weeks": weeks,
             "commit": commit[:7], "dirty": dirty, "dataset": dataset, "report": report}
    data = json.loads(path.read_text()) if path.exists() else {}
    data[card] = entry
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(dict(sorted(data.items())), indent=2) + "\n")
    return entry
